  "result": {
    "payloads": [
      {
        "text": "{\n  \"taskJudgement\": {\n    \"admitted\": true,\n    \"demandLevel\": \"strong\",\n    \"primaryType\": \"教程\",\n    \"reason\": \"用户需要可直接执行的Git SSH配置与代码拉取流程，步骤明确且具有较强实用价值。\"\n  },\n  \"platform\": {\n    \"target\": \"小红书\",\n    \"expressionType\": \"信息型\",\n    \"audience\": \"搜索Git SSH配置方法、希望快速拉取远程代码的新手用户\",\n    \"openingMethod\": \"结论前置，直接说明完整配置路径和适用边界\",\n    \"bodyStructure\": \"总述结论—生成密钥—添加公钥—验证连接—拉取代码—总结排错\",\n    \"iconDictionary\": {},\n    \"sampleEvidence\": \"not_provided\"\n  },\n  \"title\": \"Git配置SSH拉取代码，完整流程\",\n  \"body\": \"Git配置SSH拉取代码，需要依次完成生成密钥、添加公钥、验证连接和使用SSH地址克隆。配置成功后，同一台电脑上的后续git pull和git push都可以通过SSH认证。\\n\\n一、准备Git身份信息\\n先确认Git已经安装。用户名和邮箱主要用于记录提交者身份，可在终端执行：\\ngit config --global user.name \\\"你的用户名\\\"\\ngit config --global user.email \\\"你的邮箱\\\"\\n它们不是SSH密钥，也不能代替平台账户认证。\\n\\n二、生成SSH密钥\\n在Git Bash或兼容终端运行：\\nssh-keygen -t ed25519 -C \\\"你的邮箱\\\"\\n按提示确认保存位置，可使用默认路径，也可设置密钥密码。默认会生成id_ed25519和id_ed25519.pub两个文件。前者是私钥，必须保密；后者是公钥，可以添加到代码托管平台。旧系统不支持Ed25519时，可使用RSA 4096位密钥。\\n\\n三、把公钥添加到平台\\n查看并复制id_ed25519.pub的完整内容。在GitHub进入Settings，再打开SSH and GPG keys，选择New SSH key，填写标题并粘贴公钥。GitLab等平台也需要在账户的SSH Keys设置中完成同类操作，不能上传私钥。\\n\\n四、验证连接并拉取代码\\n使用GitHub时执行：\\nssh -T git@github.com\\n首次连接可能要求确认主机信息。认证成功后，在仓库页面复制SSH格式地址，再执行：\\ngit clone git@github.com:user/repo.git\\n进入已克隆的仓库后，运行git pull即可拉取更新。\\n\\n如果验证失败，优先检查公钥是否完整、添加的平台账户是否正确，以及克隆地址是否为SSH格式。核心顺序不要打乱：本地生成密钥、平台登记公钥、测试认证，最后再克隆仓库。\",\n  \"tags\": [\n    \"#Git\",\n    \"#SSH\",\n    \"#代码拉取\",\n    \"#GitHub\",\n    \"#开发工具\",\n    \"#新手教程\"\n  ],\n  \"imagePlan\": [\n    {\n      \"kind\": \"hero\",\n      \"headline\": \"Git配置SSH拉取代码\",\n      \"subtitle\": \"从生成密钥到成功克隆的完整流程\",\n      \"bullets\": [\n        \"生成本地密钥\",\n        \"平台添加公钥\",\n        \"验证后使用SSH地址克隆\"\n      ],\n      \"prompt\": \"小红书信息型教程封面，深色代码编辑器背景，中央展示Git、SSH密钥和远程仓库之间的连接关系，标题为“Git配置SSH拉取代码”，副标题为“从生成密钥到成功克隆的完整流程”，排版清晰克制，无人物、无品牌Logo、无水印、无二维码。\"\n    },\n    {\n      \"kind\": \"steps\",\n      \"headline\": \"第一步：生成SSH密钥\",\n      \"subtitle\": \"认清私钥与公钥，避免传错文件\",\n      \"bullets\": [\n        \"运行ssh-keygen -t ed25519 -C \\\"你的邮箱\\\"\",\n        \"id_ed25519是私钥，必须保密\",\n        \"id_ed25519.pub是公钥，可添加到平台\"\n      ],\n      \"prompt\": \"小红书竖版技术教程页，终端窗口展示生成Ed25519密钥的命令，旁边用文件卡片区分id_ed25519私钥与id_ed25519.pub公钥，明确标注“私钥保密”和“公钥可添加”，信息层级清楚，无Logo、无水印。\"\n    },\n    {\n      \"kind\": \"steps\",\n      \"headline\": \"第二步：添加并验证公钥\",\n      \"subtitle\": \"平台登记完成后测试SSH认证\",\n      \"bullets\": [\n        \"复制公钥文件的完整内容\",\n        \"在账户SSH Keys设置中添加\",\n        \"运行ssh -T git@github.com验证\"\n      ],\n      \"prompt\": \"小红书竖版步骤信息图，展示复制公钥、进入账户SSH Keys设置、运行验证命令的三段流程，用箭头连接，界面采用通用代码托管平台示意，不出现不一致Logo，不展示真实账号信息，无水印。\"\n    },\n    {\n      \"kind\": \"summary\",\n      \"headline\": \"第三步：克隆与排错\",\n      \"subtitle\": \"确认使用SSH格式的仓库地址\",\n      \"bullets\": [\n        \"执行git clone git@github.com:user/repo.git\",\n        \"后续使用git pull拉取更新\",\n        \"失败时检查公钥、账户和地址格式\"\n      ],\n      \"prompt\": \"小红书竖版技术总结页，上半部分展示SSH格式克隆命令和git pull，下半部分为三项排错清单：公钥完整、平台账户正确、地址为SSH格式；使用简洁终端视觉与高对比文字，无人物、无Logo、无水印、无二维码。\"\n    }\n  ],\n  \"sources\": [\n    \"https://docs.github.com/zh/authentication/connecting-to-github-with-ssh/generating-a-new-ssh-key-and-adding-it-to-the-ssh-agent\",\n    \"https://docs.github.com/zh/authentication/connecting-to-github-with-ssh/adding-a-new-ssh-key-to-your-github-account\",\n    \"https://docs.github.com/zh/enterprise-server@3.16/get-started/git-basics/set-up-git\",\n    \"https://lab.cs.tsinghua.edu.cn/rust/git/\"\n  ],\n  \"expressionReferences\": [],\n  \"riskFlags\": [],\n  \"fabricatedExperience\": false,\n  \"unverifiedClaims\": []\n}",
